#include "knn.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>

typedef struct {Model model;Prediction *predictions;int correct;double rmse;} Result;
typedef struct {int classifier,regressor;} Best;
typedef struct {int values[400],count;} Selection;
typedef struct {
 Dataset data;Model models[400];int model_count;Result *results,*loo;Best selected;Features features;int folds[MAX_ROWS],labelled,targets;
 Prediction test_class[MAX_TEST],test_reg[MAX_TEST];Orders test_orders;
} Analysis;
static int minimum(int a,int b){return a<b?a:b;}
static Selection indices(int count){Selection s={0};for(int j=0;j<count;j++)s.values[s.count++]=j;return s;}
static void clear_lines(Lines *lines){for(int j=0;j<lines->count;j++)free(lines->values[j]);free(lines->values);*lines=(Lines){0};}
static void finish_part(Lines *lines,Lines *part){append_part(lines,part);clear_lines(part);}
static Result *initialize_results(const Model *models,int count,int rows){Result *results=calloc((size_t)count,sizeof *results);if(count&&!results)exit(1);for(int j=0;j<count;j++){results[j].model=models[j];results[j].predictions=calloc((size_t)rows,sizeof *results[j].predictions);if(rows&&!results[j].predictions)exit(1);}return results;}
static void finish_results(Result *results,int count,const Rows *rows){for(int j=0;j<count;j++){double errors[MAX_ROWS];for(int i=0;i<rows->count;i++){Prediction p=results[j].predictions[i];results[j].correct+=p.label==rows->values[i]->label_index;errors[i]=p.estimate-rows->values[i]->target;}results[j].rmse=rmse(errors,rows->count);}}
static void free_results(Result *results,int count){for(int j=0;j<count;j++)free(results[j].predictions);free(results);}
static Result *cross_validate(const Model *models,int model_count,const Rows *rows,Features features,int dimension,int folds){
 Result *results=initialize_results(models,model_count,rows->count);int assignment[MAX_ROWS];stratified(rows,folds,assignment);
 for(int f=0;f<folds;f++){Rows training=training_rows(rows,assignment,f),queries={0};int positions[MAX_ROWS];for(int j=0;j<rows->count;j++)if(assignment[j]==f){positions[queries.count]=j;queries.values[queries.count++]=rows->values[j];}Orders cache[8]={0};bool found[8]={0};
  for(int j=0;j<model_count;j++){Model m=models[j];int key=m.scaling*4+m.metric;if(!found[key]){cache[key]=neighbor_orders(&training,&queries,m.scaling,m.metric,features,dimension);found[key]=true;}Orders o=cache[key];for(int k=0;k<queries.count;k++)results[j].predictions[positions[k]]=predict_order(o.values+k*o.references,o.references,m.k,m.weighting);}
  for(int key=0;key<8;key++)free(cache[key].values);
 }
 finish_results(results,model_count,rows);return results;
}
static Result *leave_one_out(const Model *models,int model_count,const Rows *rows,Features features,int dimension){
 Result *results=initialize_results(models,model_count,rows->count);
 for(int i=0;i<rows->count;i++){Rows training={0},queries={.count=1,.values={rows->values[i]}};for(int j=0;j<rows->count;j++)if(j!=i)training.values[training.count++]=rows->values[j];Orders cache[8]={0};bool found[8]={0};
  for(int j=0;j<model_count;j++){Model m=models[j];int key=m.scaling*4+m.metric;if(!found[key]){cache[key]=neighbor_orders(&training,&queries,m.scaling,m.metric,features,dimension);found[key]=true;}results[j].predictions[i]=predict_order(cache[key].values,training.count,m.k,m.weighting);}for(int key=0;key<8;key++)free(cache[key].values);
 }
 finish_results(results,model_count,rows);return results;
}
static Best best(const Result *results,Selection selection){Best b={selection.values[0],selection.values[0]};for(int j=1;j<selection.count;j++){int i=selection.values[j];if(results[i].correct>results[b.classifier].correct)b.classifier=i;if(four(results[i].rmse)<four(results[b.regressor].rmse))b.regressor=i;}return b;}
static int correct(const Rows *rows,const Prediction *predictions){int count=0;for(int j=0;j<rows->count;j++)count+=rows->values[j]->label_index>=0&&rows->values[j]->label_index==predictions[j].label;return count;}
static int errors_for(const Rows *rows,const Prediction *predictions,double *errors,double *targets){int count=0;for(int j=0;j<rows->count;j++)if(rows->values[j]->has_target){errors[count]=predictions[j].estimate-rows->values[j]->target;if(targets)targets[count]=rows->values[j]->target;count++;}return count;}
static int compare_ids(const void *left,const void *right){const Row *a=*(Row *const *)left,*b=*(Row *const *)right;return strcmp(a->id,b->id);}
static Rows sorted_rows(Rows rows){if(rows.count>1)qsort(rows.values,(size_t)rows.count,sizeof *rows.values,compare_ids);return rows;}
static const char *label_counts(const Dataset *d,const Rows *rows){static char buffers[32][8192];static unsigned next;char *text=buffers[next++%32];text[0]='\0';int counts[MAX_CLASSES]={0};for(int j=0;j<rows->count;j++)counts[rows->values[j]->label_index]++;for(int j=0;j<d->label_count;j++)snprintf(text+strlen(text),8192-strlen(text),"%s%s %d",j?" ":"",d->labels[j],counts[j]);return text;}
static Lines evaluation(const Dataset *d,const Rows *rows,const Prediction *predictions){
 int matrix[MAX_CLASSES][MAX_CLASSES]={0};for(int j=0;j<rows->count;j++){int label=rows->values[j]->label_index;if(label>=0)matrix[label][predictions[j].label]++;}Lines lines={0};char text[8192];strcpy(text,"true\\predicted");for(int j=0;j<d->label_count;j++){strcat(text," ");strcat(text,d->labels[j]);}add_line(&lines,"%s",text);
 for(int j=0;j<d->label_count;j++){strcpy(text,d->labels[j]);for(int k=0;k<d->label_count;k++)snprintf(text+strlen(text),sizeof text-strlen(text)," %d",matrix[j][k]);add_line(&lines,"%s",text);}double sums[3]={0};int counts[3]={0};
 for(int j=0;j<d->label_count;j++){int actual=0,predicted=0;for(int k=0;k<d->label_count;k++){actual+=matrix[j][k];predicted+=matrix[k][j];}int tp=matrix[j][j],numerators[3]={tp,tp,2*tp},denominators[3]={predicted,actual,predicted+actual};for(int k=0;k<3;k++)if(denominators[k]){sums[k]+=(double)numerators[k]/denominators[k];counts[k]++;}add_line(&lines,"class %s precision %s recall %s f1 %s support %d",d->labels[j],fraction_metric(tp,predicted),fraction_metric(tp,actual),fraction_metric(2*tp,predicted+actual),actual);}
 const char *averages[3];for(int k=0;k<3;k++)averages[k]=counts[k]?real(sums[k]/counts[k]):"-";add_line(&lines,"macro precision %s recall %s f1 %s",averages[0],averages[1],averages[2]);return lines;
}
static Lines bins(const Dataset *d,const Rows *rows,const Prediction *predictions){const Settings *s=&d->settings;int counts[100]={0},correct_counts[100]={0};double sums[100]={0};for(int j=0;j<rows->count;j++){Row *r=rows->values[j];if(r->label_index<0)continue;Prediction p=predictions[j];int bin=0;while(bin<s->bin_count&&p.share>=s->bins[bin])bin++;counts[bin]++;correct_counts[bin]+=p.label==r->label_index;sums[bin]+=p.share;}Lines lines={0};for(int j=0;j<=s->bin_count;j++){double lower=j?s->bins[j-1]:0;if(!counts[j])add_line(&lines,"bin %s rows 0",fixed(lower,2));else add_line(&lines,"bin %s rows %d correct %s share %s",fixed(lower,2),counts[j],ratio(correct_counts[j],counts[j]),real(sums[j]/counts[j]));}return lines;}
static Features without_feature(Features features,int position){Features out={0};for(int j=0;j<features.count;j++)if(j!=position)out.values[out.count++]=features.values[j];return out;}
static const char *feature_names(const Dataset *d,Features features){static char buffers[8][256];static unsigned next;char *text=buffers[next++%8];text[0]='\0';for(int j=0;j<features.count;j++){if(j)strcat(text," ");strcat(text,d->feature_names[features.values[j]]);}return text;}
static Lines feature_lines(const Analysis *a){const Dataset *d=&a->data;Model m=a->models[a->selected.classifier];Features features=a->features,selected=features;int best_count=a->results[a->selected.classifier].correct,n=d->training.count;Lines lines={0};add_line(&lines,"feature_selection %s",model_notation(m));add_line(&lines,"start features %s correct %s",feature_names(d,features),ratio(best_count,n));int step=0;
 while(features.count>=3){int counts[MAX_FEATURES],choice=0;for(int j=0;j<features.count;j++){Result *result=cross_validate(&m,1,&d->training,without_feature(features,j),d->feature_count,d->settings.folds);counts[j]=result[0].correct;free_results(result,1);if(counts[j]>counts[choice])choice=j;}char candidates[512]="";for(int j=0;j<features.count;j++)snprintf(candidates+strlen(candidates),sizeof candidates-strlen(candidates),"%s%s %d",j?" ":"",d->feature_names[features.values[j]],counts[j]);int removed=features.values[choice];features=without_feature(features,choice);add_line(&lines,"step %d remove %s correct %s candidates %s",++step,d->feature_names[removed],ratio(counts[choice],n),candidates);if(counts[choice]>=best_count){best_count=counts[choice];selected=features;}}
 Prediction test[MAX_TEST];predict_rows(m,&d->training,&d->testing,selected,d->feature_count,test);add_line(&lines,"selected features %s correct %s",feature_names(d,selected),ratio(best_count,n));add_line(&lines,"selected test %s",ratio(correct(&d->testing,test),a->labelled));return lines;
}
static Lines nested_lines(const Analysis *a){const Dataset *d=&a->data;Lines lines={0};add_line(&lines,"nested_cross_validation folds %d",d->settings.folds);double nested_errors[MAX_ROWS];int total_correct=0;
 for(int f=0;f<d->settings.folds;f++){Rows training=training_rows(&d->training,a->folds,f),queries={0};int positions[MAX_ROWS];for(int j=0;j<d->training.count;j++)if(a->folds[j]==f){positions[queries.count]=j;queries.values[queries.count++]=d->training.values[j];}Result *inner=cross_validate(a->models,a->model_count,&training,a->features,d->feature_count,d->settings.folds);Best selected=best(inner,indices(a->model_count));Prediction cp[MAX_ROWS],rp[MAX_ROWS];predict_rows(a->models[selected.classifier],&training,&queries,a->features,d->feature_count,cp);predict_rows(a->models[selected.regressor],&training,&queries,a->features,d->feature_count,rp);int count=correct(&queries,cp);total_correct+=count;double errors[MAX_ROWS];errors_for(&queries,rp,errors,NULL);for(int j=0;j<queries.count;j++)nested_errors[positions[j]]=errors[j];add_line(&lines,"fold %d classifier %s inner %s outer %s",f+1,model_notation(a->models[selected.classifier]),real((double)inner[selected.classifier].correct/training.count),ratio(count,queries.count));add_line(&lines,"fold %d regressor %s inner %s outer %s",f+1,model_notation(a->models[selected.regressor]),real(inner[selected.regressor].rmse),real(rmse(errors,queries.count)));free_results(inner,a->model_count);}
 add_line(&lines,"nested accuracy %s rmse %s",ratio(total_correct,d->training.count),real(rmse(nested_errors,d->training.count)));return lines;
}
static bool model_matches(Model m,int kind,int value){if(kind==0)return m.k==value;if(kind==1)return m.metric==(Metric)value;if(kind==2)return m.weighting==(Weighting)value;return m.scaling==(ScalingMethod)value;}
static Lines best_per(const Analysis *a,int kind){const Settings *s=&a->data.settings;const char *kinds[4]={"k","metric","weighting","scaling"};int count=kind==0?s->k_count:kind==1?s->metric_count:kind==2?s->weighting_count:s->scaling_count;Lines lines={0};add_line(&lines,"best per %s",kinds[kind]);for(int j=0;j<count;j++){int value=kind==0?s->k[j]:kind==1?(int)s->metrics[j]:kind==2?(int)s->weightings[j]:(int)s->scalings[j];Selection selection={0};for(int k=0;k<a->model_count;k++)if(model_matches(a->models[k],kind,value))selection.values[selection.count++]=k;Best selected=best(a->results,selection);Result c=a->results[selected.classifier],r=a->results[selected.regressor];char number[32];snprintf(number,sizeof number,"%d",value);const char *text=kind==0?number:kind==1?metric_names[value]:kind==2?weighting_names[value]:scaling_names[value];add_line(&lines,"%s=%s classifier %s accuracy %s regressor %s rmse %s",kinds[kind],text,model_notation(c.model),real((double)c.correct/a->data.training.count),model_notation(r.model),real(r.rmse));}return lines;}
static Selection rank_models(const Analysis *a,bool regression){Selection order=indices(a->model_count);for(int j=1;j<order.count;j++){int value=order.values[j],k=j;while(k>0){int previous=order.values[k-1];bool before=regression?(four(a->results[value].rmse)<four(a->results[previous].rmse)||(four(a->results[value].rmse)==four(a->results[previous].rmse)&&value<previous)):(a->results[value].correct>a->results[previous].correct||(a->results[value].correct==a->results[previous].correct&&value<previous));if(!before)break;order.values[k]=previous;k--;}order.values[k]=value;}return order;}
static Lines metrics_lines(const Analysis *a){
 const Dataset *d=&a->data;const Settings *s=&d->settings;int n=d->training.count;Result c=a->results[a->selected.classifier],r=a->results[a->selected.regressor];Lines lines={0},part={0};
 add_line(&lines,"data train %d test %d labelled %d targets %d features %d classes %d",n,d->testing.count,a->labelled,a->targets,d->feature_count,d->label_count);add_line(&lines,"classes %s",label_counts(d,&d->training));
 for(int j=0;j<s->scaling_count;j++){ScalingMethod method=s->scalings[j];Scaling scale=compute_scaling(&d->training,method,d->feature_count);add_line(&part,"scaling %s",scaling_names[method]);for(int k=0;k<d->feature_count;k++)add_line(&part,"%s center %s scale %s",d->feature_names[k],fixed(scale.centers[k],6),fixed(scale.scales[k],6));finish_part(&lines,&part);}
 add_line(&part,"folds %d",s->folds);for(int f=0;f<s->folds;f++){Rows rows={0};for(int j=0;j<n;j++)if(a->folds[j]==f)rows.values[rows.count++]=d->training.values[j];add_line(&part,"fold %d size %d %s",f+1,rows.count,label_counts(d,&rows));}finish_part(&lines,&part);
 add_line(&part,"grid %d",a->model_count);add_line(&part,"best_classifier %s correct %s rmse %s",model_notation(c.model),ratio(c.correct,n),real(c.rmse));add_line(&part,"best_regressor %s rmse %s correct %s",model_notation(r.model),real(r.rmse),ratio(r.correct,n));finish_part(&lines,&part);
 Selection accuracy=rank_models(a,false),regression=rank_models(a,true);add_line(&part,"top %d by accuracy",s->top);for(int j=0;j<minimum(s->top,accuracy.count);j++){Result value=a->results[accuracy.values[j]];add_line(&part,"%d %s correct %s rmse %s",j+1,model_notation(value.model),ratio(value.correct,n),real(value.rmse));}finish_part(&lines,&part);
 add_line(&part,"top %d by rmse",s->top);for(int j=0;j<minimum(s->top,regression.count);j++){Result value=a->results[regression.values[j]];add_line(&part,"%d %s rmse %s correct %s",j+1,model_notation(value.model),real(value.rmse),ratio(value.correct,n));}finish_part(&lines,&part);for(int kind=0;kind<4;kind++){part=best_per(a,kind);finish_part(&lines,&part);}
 add_line(&part,"classifier folds");for(int f=0;f<s->folds;f++){int count=0,size=0;for(int j=0;j<n;j++)if(a->folds[j]==f){size++;count+=c.predictions[j].label==d->train[j].label_index;}add_line(&part,"fold %d correct %s",f+1,ratio(count,size));}finish_part(&lines,&part);
 add_line(&part,"regressor folds");for(int f=0;f<s->folds;f++){double errors[MAX_ROWS];int count=0;for(int j=0;j<n;j++)if(a->folds[j]==f)errors[count++]=r.predictions[j].estimate-d->train[j].target;add_line(&part,"fold %d size %d rmse %s",f+1,count,real(rmse(errors,count)));}finish_part(&lines,&part);
 add_line(&part,"cross_validation classes");Lines detail=evaluation(d,&d->training,c.predictions);append_lines(&part,&detail);clear_lines(&detail);finish_part(&lines,&part);add_line(&part,"cross_validation reliability");detail=bins(d,&d->training,c.predictions);append_lines(&part,&detail);clear_lines(&detail);finish_part(&lines,&part);
 add_line(&part,"mcnemar");for(int j=0;j<s->metric_count;j++){Selection selection={0};for(int k=0;k<a->model_count;k++)if(a->models[k].metric==s->metrics[j])selection.values[selection.count++]=k;int comparison=best(a->results,selection).classifier,b=0,cc=0;for(int k=0;k<n;k++){bool first=c.predictions[k].label==d->train[k].label_index,second=a->results[comparison].predictions[k].label==d->train[k].label_index;b+=first&&!second;cc+=second&&!first;}int delta=abs(b-cc)-1;if(delta<0)delta=0;int u=delta*delta;add_line(&part,"%s b %d c %d statistic %s significant %s",model_notation(a->models[comparison]),b,cc,b+cc?fraction_metric(u,b+cc):"0/1 0.0000",1000*u>3841*(b+cc)?"yes":"no");}finish_part(&lines,&part);
 Result loo_c=a->loo[0],loo_r=a->loo[1];int class_errors[MAX_CLASSES]={0};for(int j=0;j<n;j++)if(loo_c.predictions[j].label!=d->train[j].label_index)class_errors[d->train[j].label_index]++;char text[8192]="class_errors";for(int j=0;j<d->label_count;j++)snprintf(text+strlen(text),sizeof text-strlen(text)," %s %d",d->labels[j],class_errors[j]);add_line(&part,"leave_one_out classifier %s",model_notation(c.model));add_line(&part,"errors %s",ratio(n-loo_c.correct,n));add_line(&part,"%s",text);Rows by_id=sorted_rows(d->training);for(int j=0;j<n;j++){Row *row=by_id.values[j];Prediction p=loo_c.predictions[row->index];if(p.label!=row->label_index)add_line(&part,"%s true %s predicted %s share %s",row->id,row->label,d->labels[p.label],real(p.share));}finish_part(&lines,&part);
 double residuals[MAX_ROWS];errors_for(&d->training,loo_r.predictions,residuals,NULL);Selection largest=indices(n);for(int j=1;j<n;j++){int value=largest.values[j],k=j;while(k>0){int previous=largest.values[k-1];double first=four(fabs(residuals[value])),second=four(fabs(residuals[previous]));if(first<second||(first==second&&strcmp(d->train[value].id,d->train[previous].id)>=0))break;largest.values[k]=previous;k--;}largest.values[k]=value;}
 add_line(&part,"leave_one_out regressor %s",model_notation(r.model));add_line(&part,"rmse %s mae %s",real(rmse(residuals,n)),real(mae(residuals,n)));add_line(&part,"largest %d residuals",s->top);for(int j=0;j<minimum(s->top,n);j++){int i=largest.values[j];add_line(&part,"%s target %s estimate %s residual %s",d->train[i].id,real(d->train[i].target),real(loo_r.predictions[i].estimate),real(residuals[i]));}finish_part(&lines,&part);
 add_line(&part,"leave_one_out by k metric=%s weighting=%s scaling=%s",metric_names[c.model.metric],weighting_names[c.model.weighting],scaling_names[c.model.scaling]);for(int j=0;j<s->k_count;j++){Result value=a->loo[j+2];add_line(&part,"k=%d correct %s rmse %s",s->k[j],ratio(value.correct,n),real(value.rmse));}finish_part(&lines,&part);part=nested_lines(a);finish_part(&lines,&part);part=feature_lines(a);finish_part(&lines,&part);
 add_line(&part,"test classification %s",model_notation(c.model));add_line(&part,"labelled %d correct %s",a->labelled,ratio(correct(&d->testing,a->test_class),a->labelled));detail=evaluation(d,&d->testing,a->test_class);append_lines(&part,&detail);clear_lines(&detail);finish_part(&lines,&part);add_line(&part,"test reliability");detail=bins(d,&d->testing,a->test_class);append_lines(&part,&detail);clear_lines(&detail);finish_part(&lines,&part);
 Selection uncertain=indices(d->testing.count);for(int j=1;j<uncertain.count;j++){int value=uncertain.values[j],k=j;Prediction p=a->test_class[value];double first=four(p.share-p.runner_share);while(k>0){int previous=uncertain.values[k-1];Prediction q=a->test_class[previous];double second=four(q.share-q.runner_share);if(first>second||(first==second&&value>=previous))break;uncertain.values[k]=previous;k--;}uncertain.values[k]=value;}
 add_line(&part,"uncertain %d test rows",s->top);for(int j=0;j<minimum(s->top,uncertain.count);j++){int i=uncertain.values[j];Row row=d->test[i];Prediction p=a->test_class[i];add_line(&part,"%s predicted %s share %s runner_up %s share %s margin %s true %s",row.id,d->labels[p.label],real(p.share),p.runner<0?"-":d->labels[p.runner],real(p.runner_share),real(p.share-p.runner_share),row.label_index<0?"-":row.label);}finish_part(&lines,&part);
 double test_errors[MAX_TEST],targets[MAX_TEST];int target_count=errors_for(&d->testing,a->test_reg,test_errors,targets);add_line(&part,"test regression %s",model_notation(r.model));add_line(&part,"targets %d rmse %s mae %s r2 %s",a->targets,real(rmse(test_errors,target_count)),real(mae(test_errors,target_count)),real(r_squared(test_errors,targets,target_count)));for(int label=0;label<d->label_count;label++){double errors[MAX_TEST];int count=0;for(int j=0;j<d->testing.count;j++)if(d->test[j].has_target&&d->test[j].label_index==label)errors[count++]=a->test_reg[j].estimate-d->test[j].target;add_line(&part,"class %s targets %d rmse %s",d->labels[label],count,count?real(rmse(errors,count)):"-");}finish_part(&lines,&part);
 add_line(&part,"misclassified test rows");int count=0;for(int j=0;j<d->testing.count;j++){Row row=d->test[j];Prediction p=a->test_class[j];if(row.label_index<0||p.label==row.label_index)continue;count++;add_line(&part,"%s true %s predicted %s share %s",row.id,row.label,d->labels[p.label],real(p.share));for(int k=0;k<minimum(c.model.k,a->test_orders.references);k++){Neighbor neighbor=a->test_orders.values[j*a->test_orders.references+k];add_line(&part,"  %s %s %s",neighbor.row->id,neighbor.row->label,real(neighbor.distance));}}add_line(&part,"count %d",count);finish_part(&lines,&part);return lines;
}
static Lines learning_lines(const Analysis *a){const Dataset *d=&a->data;Lines lines={0};add_line(&lines,"n,train_size,correct,accuracy,rmse");for(int j=0;j<d->settings.curve.count;j++){int limit=d->settings.curve.values[j],counts[MAX_CLASSES]={0};Rows training={0};for(int k=0;k<d->training.count;k++){Row *r=d->training.values[k];if(counts[r->label_index]<limit){counts[r->label_index]++;training.values[training.count++]=r;}}Prediction cp[MAX_TEST],rp[MAX_TEST];predict_rows(a->models[a->selected.classifier],&training,&d->testing,a->features,d->feature_count,cp);predict_rows(a->models[a->selected.regressor],&training,&d->testing,a->features,d->feature_count,rp);int count=correct(&d->testing,cp);double errors[MAX_TEST];int targets=errors_for(&d->testing,rp,errors,NULL);add_line(&lines,"%d,%d,%d,%s,%s",limit,training.count,count,real((double)count/a->labelled),real(rmse(errors,targets)));}return lines;}
typedef struct {double *distances;int width;} Space;
static Space classifier_space(const Analysis *a){const Dataset *d=&a->data;Model m=a->models[a->selected.classifier];Scaling s=compute_scaling(&d->training,m.scaling,d->feature_count);double vectors[MAX_ROWS*MAX_FEATURES],query[MAX_FEATURES];for(int j=0;j<d->training.count;j++)transform(s,d->training.values[j],a->features,vectors+j*a->features.count);int count=d->training.count+d->testing.count;Space space={.width=d->training.count};space.distances=malloc((size_t)count*space.width*sizeof *space.distances);if(!space.distances)exit(1);for(int j=0;j<count;j++){const Row *q=j<d->training.count?&d->train[j]:&d->test[j-d->training.count];transform(s,q,a->features,query);for(int k=0;k<d->training.count;k++)space.distances[q->index*space.width+d->train[k].index]=distance(query,vectors+k*a->features.count,a->features.count,m.metric);}return space;}
static void space_order(Space space,const Row *query,const Rows *references,Neighbor *order){for(int j=0;j<references->count;j++){Row *r=references->values[j];order[j]=(Neighbor){r,space.distances[query->index*space.width+r->index]};}sort_neighbors(order,references->count);}
static Rows except_row(const Rows *rows,const Row *row){Rows references={0};for(int j=0;j<rows->count;j++)if(rows->values[j]!=row)references.values[references.count++]=rows->values[j];return references;}
typedef struct {Rows rows;int scans;} Condensation;
static Condensation condense(Space space,Rows rows){rows=sorted_rows(rows);Condensation result={.rows={.count=1,.values={rows.values[0]}}};bool present[MAX_ROWS]={0};present[rows.values[0]->index]=true;for(;;){result.scans++;bool added=false;for(int j=0;j<rows.count;j++){Row *r=rows.values[j];if(present[r->index])continue;Neighbor order[MAX_ROWS];space_order(space,r,&result.rows,order);if(order[0].row->label_index!=r->label_index){result.rows.values[result.rows.count++]=r;present[r->index]=true;added=true;}}if(!added)break;}result.rows=sorted_rows(result.rows);return result;}
static Lines prototype_ids(const char *name,Rows rows){Lines lines={0};add_line(&lines,"prototypes %s",name);rows=sorted_rows(rows);for(int first=0;first<rows.count;first+=10){char text[128]="";for(int j=first;j<minimum(first+10,rows.count);j++){if(j>first)strcat(text," ");strcat(text,rows.values[j]->id);}add_line(&lines,"%s",text);}return lines;}
static Lines prototype_lines(const Analysis *a){
 const Dataset *d=&a->data;const Settings *s=&d->settings;Model m=a->models[a->selected.classifier];Space space=classifier_space(a);Lines lines={0},part={0};add_line(&lines,"space %s",model_notation(m));Rows edited=sorted_rows(d->training);add_line(&part,"editing k=%d",s->edit_k);
 for(int pass=1;;pass++){Rows removed={0};Prediction predictions[MAX_ROWS];for(int j=0;j<edited.count;j++){Row *r=edited.values[j];Rows references=except_row(&edited,r);Neighbor order[MAX_ROWS];space_order(space,r,&references,order);Prediction p=predict_order(order,references.count,s->edit_k,m.weighting);if(p.label!=r->label_index){predictions[removed.count]=p;removed.values[removed.count++]=r;}}add_line(&part,"pass %d removed %d",pass,removed.count);for(int j=0;j<removed.count;j++){Row *r=removed.values[j];Prediction p=predictions[j];add_line(&part,"  %s true %s predicted %s share %s",r->id,r->label,d->labels[p.label],real(p.share));}if(!removed.count)break;bool skip[MAX_ROWS]={0};for(int j=0;j<removed.count;j++)skip[removed.values[j]->index]=true;Rows next={0};for(int j=0;j<edited.count;j++)if(!skip[edited.values[j]->index])next.values[next.count++]=edited.values[j];edited=next;}
 add_line(&part,"edited size %d removed %d",edited.count,d->training.count-edited.count);finish_part(&lines,&part);Condensation condensed=condense(space,d->training),edited_condensed=condense(space,edited);add_line(&part,"condensing original scans %d size %d",condensed.scans,condensed.rows.count);add_line(&part,"condensing edited scans %d size %d",edited_condensed.scans,edited_condensed.rows.count);finish_part(&lines,&part);
 Rows sets[4]={d->training,edited,condensed.rows,edited_condensed.rows};const char *set_names[4]={"original","edited","condensed","edited_condensed"};for(int j=0;j<4;j++){int knn=0,one=0;for(int k=0;k<d->testing.count;k++){Row *q=d->testing.values[k];if(q->label_index<0)continue;Neighbor order[MAX_ROWS];space_order(space,q,&sets[j],order);Prediction p=predict_order(order,sets[j].count,m.k,m.weighting);knn+=p.label==q->label_index;one+=order[0].row->label_index==q->label_index;}add_line(&part,"set %s size %d %s knn %s 1nn %s",set_names[j],sets[j].count,label_counts(d,&sets[j]),ratio(knn,a->labelled),ratio(one,a->labelled));}finish_part(&lines,&part);part=prototype_ids("condensed",condensed.rows);finish_part(&lines,&part);part=prototype_ids("edited_condensed",edited_condensed.rows);finish_part(&lines,&part);
 add_line(&part,"borders");int total_border=0;Rows by_id=sorted_rows(d->training);for(int label=0;label<d->label_count;label++){int count=0,border=0;double same=0,other=0;for(int j=0;j<by_id.count;j++){Row *q=by_id.values[j];if(q->label_index!=label)continue;count++;Rows references=except_row(&d->training,q);Neighbor order[MAX_ROWS];space_order(space,q,&references,order);border+=order[0].row->label_index!=label;bool found_same=false,found_other=false;for(int k=0;k<references.count;k++){Neighbor neighbor=order[k];if(!found_same&&neighbor.row->label_index==label){same+=neighbor.distance;found_same=true;}if(!found_other&&neighbor.row->label_index!=label){other+=neighbor.distance;found_other=true;}if(found_same&&found_other)break;}}total_border+=border;add_line(&part,"class %s size %d border %d same %s other %s",d->labels[label],count,border,real(same/count),real(other/count));}add_line(&part,"border total %s",ratio(total_border,d->training.count));finish_part(&lines,&part);
 int occurrences[MAX_ROWS]={0};for(int j=0;j<d->testing.count;j++)for(int k=0;k<minimum(m.k,a->test_orders.references);k++)occurrences[a->test_orders.values[j*a->test_orders.references+k].row->index]++;Selection order=indices(d->training.count);for(int j=1;j<order.count;j++){int value=order.values[j],k=j;while(k>0){int previous=order.values[k-1];if(occurrences[value]<occurrences[previous]||(occurrences[value]==occurrences[previous]&&strcmp(d->train[value].id,d->train[previous].id)>=0))break;order.values[k]=previous;k--;}order.values[k]=value;}add_line(&part,"hubs k=%d queries %d",m.k,d->testing.count);int anti=0;for(int j=0;j<d->training.count;j++)anti+=!occurrences[j];for(int j=0;j<minimum(s->top,order.count);j++){int i=order.values[j];add_line(&part,"%s %s %d",d->train[i].id,d->train[i].label,occurrences[i]);}add_line(&part,"anti_hubs %d",anti);finish_part(&lines,&part);free(space.distances);return lines;
}
int main(void){
 Analysis *a=calloc(1,sizeof *a);if(!a)return 1;read_dataset(&a->data);Dataset *d=&a->data;Settings *s=&d->settings;for(int j=0;j<d->feature_count;j++)a->features.values[a->features.count++]=j;
 for(int k=0;k<s->k_count;k++)for(int metric=0;metric<s->metric_count;metric++)for(int weight=0;weight<s->weighting_count;weight++)for(int scale=0;scale<s->scaling_count;scale++)a->models[a->model_count++]=(Model){s->k[k],s->metrics[metric],s->weightings[weight],s->scalings[scale]};stratified(&d->training,s->folds,a->folds);a->results=cross_validate(a->models,a->model_count,&d->training,a->features,d->feature_count,s->folds);a->selected=best(a->results,indices(a->model_count));Model classifier=a->models[a->selected.classifier],regressor=a->models[a->selected.regressor];a->test_orders=neighbor_orders(&d->training,&d->testing,classifier.scaling,classifier.metric,a->features,d->feature_count);for(int j=0;j<d->testing.count;j++){a->test_class[j]=predict_order(a->test_orders.values+j*a->test_orders.references,a->test_orders.references,classifier.k,classifier.weighting);a->labelled+=d->test[j].label_index>=0;a->targets+=d->test[j].has_target;}predict_rows(regressor,&d->training,&d->testing,a->features,d->feature_count,a->test_reg);
 Model loo_models[27]={classifier,regressor};for(int j=0;j<s->k_count;j++){loo_models[j+2]=classifier;loo_models[j+2].k=s->k[j];}a->loo=leave_one_out(loo_models,s->k_count+2,&d->training,a->features,d->feature_count);Lines grid={0},predictions={0};add_line(&grid,"k,metric,weighting,scaling,correct,accuracy,rmse");for(int j=0;j<a->model_count;j++){Result r=a->results[j];Model m=r.model;add_line(&grid,"%d,%s,%s,%s,%d,%s,%s",m.k,metric_names[m.metric],weighting_names[m.weighting],scaling_names[m.scaling],r.correct,real((double)r.correct/d->training.count),real(r.rmse));}add_line(&predictions,"id,label,vote_share,estimate");for(int j=0;j<d->testing.count;j++){Prediction p=a->test_class[j];add_line(&predictions,"%s,%s,%s,%s",d->test[j].id,d->labels[p.label],real(p.share),real(a->test_reg[j].estimate));}
 const char *names[5]={"cv_grid.csv","predictions.csv","metrics.txt","learning_curve.csv","prototypes.txt"};Lines reports[5]={grid,predictions,metrics_lines(a),learning_lines(a),prototype_lines(a)};for(int j=0;j<5;j++){write_report(names[j],&reports[j]);clear_lines(&reports[j]);}free_results(a->results,a->model_count);free_results(a->loo,s->k_count+2);free(a->test_orders.values);free(s->curve.values);free(a);return 0;
}
